// Fits props generated by scripts/props/generate.py (scripts/props/out/<id>/model.glb) to the island: the footprint or
// height of the package model it replaces, a bottom-centre pivot, matte non-metal materials and WebP maps. Writes
// public/gltf/<file>, which the app serves instead of the package's own model (vite/gaesupAssets.ts: a public/ file of
// the same path wins), so the village, the decorate shelves and world GI pick it up without code changes.
// Usage: node scripts/props-normalize.mjs [ids...]    (default: every manifest item that has a generated model)
import { existsSync, mkdirSync, readFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { getBounds, NodeIO } from '@gltf-transform/core';
import { ALL_EXTENSIONS } from '@gltf-transform/extensions';
import { dedup, prune, textureCompress } from '@gltf-transform/functions';
import { MeshoptDecoder, MeshoptEncoder } from 'meshoptimizer';
import sharp from 'sharp';

const web = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const props = resolve(web, '../scripts/props');
const packageGltf = resolve(dirname(fileURLToPath(import.meta.resolve('gaesup-world'))), '../public/gltf');
const manifest = JSON.parse(readFileSync(join(props, 'manifest.json'), 'utf8'));
/** Props are a few metres from a camera ~15 m away: 512 px colour maps are plenty. */
const MAPS = { resize: [512, 512], quality: 86 };
/** The island's props are matte; generated PBR sets come with metal and gloss that read as black or white patches. */
const ROUGHNESS = 0.9;

await Promise.all([MeshoptDecoder.ready, MeshoptEncoder.ready]);
const io = new NodeIO()
  .registerExtensions(ALL_EXTENSIONS)
  .registerDependencies({ 'meshopt.decoder': MeshoptDecoder, 'meshopt.encoder': MeshoptEncoder });

function boxOf(document) {
  const { min, max } = getBounds(document.getRoot().getDefaultScene() ?? document.getRoot().listScenes()[0]);
  return { min, max, size: max.map((value, axis) => value - min[axis]) };
}

async function fit(item) {
  const source = join(props, 'out', item.id, 'model.glb');
  if (!existsSync(source)) return `${item.id}: no generated model`;
  const target = boxOf(await io.read(join(packageGltf, item.file)));
  const document = await io.read(source);
  const scene = document.getRoot().getDefaultScene() ?? document.getRoot().listScenes()[0];
  const wrapper = document.createNode(`${item.id}-fit`);
  for (const child of scene.listChildren()) {
    scene.removeChild(child);
    wrapper.addChild(child);
  }
  scene.addChild(wrapper);
  // Face the way the model it replaces faced (set `yaw` in the manifest when a generated model looks the other way),
  // and lay a long piece of furniture along the same axis; plants and rocks have no front.
  let yaw = ((item.yaw ?? 0) * Math.PI) / 180;
  const quarter = (angle) => [0, Math.sin(angle / 2), 0, Math.cos(angle / 2)];
  wrapper.setRotation(quarter(yaw));
  let turned = boxOf(document);
  const long = (size) => size[0] / size[2];
  const oriented = item.category === 'furniture';
  if (oriented && item.yaw === undefined && (long(turned.size) > 1.3) !== (long(target.size) > 1.3) && Math.abs(Math.log(long(turned.size))) > 0.26) {
    yaw += Math.PI / 2;
    wrapper.setRotation(quarter(yaw));
    turned = boxOf(document);
  }
  // Furniture keeps the old footprint (placements and spacing were made for it); plants and rocks keep its height.
  const byHeight = item.category !== 'furniture';
  const scale = byHeight
    ? target.size[1] / turned.size[1]
    : Math.min(...[0, 1, 2].map((axis) => target.size[axis] / turned.size[axis]));
  const centre = (box, axis) => (box.min[axis] + box.max[axis]) / 2;
  wrapper.setScale([scale, scale, scale]);
  wrapper.setTranslation([
    centre(target, 0) - centre(turned, 0) * scale,
    target.min[1] - turned.min[1] * scale,
    centre(target, 2) - centre(turned, 2) * scale,
  ]);
  for (const material of document.getRoot().listMaterials()) {
    material.setMetallicFactor(0).setMetallicRoughnessTexture(null).setRoughnessFactor(ROUGHNESS);
  }
  await document.transform(dedup(), prune(), textureCompress({ encoder: sharp, targetFormat: 'webp', ...MAPS }));
  const output = join(process.env['PROPS_OUTPUT'] ?? join(web, 'public/gltf'), item.file);
  mkdirSync(dirname(output), { recursive: true });
  await io.write(output, document);
  const fitted = boxOf(document);
  const metres = (size) => size.map((value) => value.toFixed(2)).join(' x ');
  return `${item.id}: ${metres(fitted.size)} m (was ${metres(target.size)}), yaw ${Math.round((yaw * 180) / Math.PI)}°`;
}

const wanted = new Set(process.argv.slice(2));
for (const item of manifest.items) {
  if (wanted.size && !wanted.has(item.id)) continue;
  console.log(await fit(item));
}
